  var rng=UnityEngine.Random.state;var oldSound=SoundManager.instance;var root=new GameObject("OfflineRewardVerification");root.SetActive(false);OfflineKeyStore.SetVerificationRoot(r.testRoot);
  try{
   SoundManager.instance=null;GameManager.Language=0;Lang.currentLang=null;GameManager.Level=0;GameManager.NewUserTapNation=true;GameManager.ViPSinirsizidle=false;GameManager.MaxGearSize=1000;Basarimlar.basarilar=new List<BasariGorev>();GunlukGorevler.tasks=new List<GunlukGorev>();UnityEngine.Random.InitState(6501);
