   var templates=AssetDatabase.FindAssets("t:GearTemplate").OrderBy(g=>g,StringComparer.Ordinal).Select(g=>AssetDatabase.LoadAssetAtPath<GearTemplate>(AssetDatabase.GUIDToAssetPath(g))).Where(t=>t!=null).Take(6).ToArray();
   if(templates.Length==0)throw new InvalidOperationException("Original GearTemplate assets missing; cannot fabricate reward templates.");
   foreach(var template in templates){string guid;long local;if(!AssetDatabase.TryGetGUIDAndLocalFileIdentifier(template,out guid,out local))throw new InvalidOperationException("Original template has no stable asset reference.");OfflineAssetReferenceCatalog.Register(guid+":"+local,template);}
   var inv=Add<InventoryManager>(root.transform,"original-inventory");inv.inventory=new List<GearInstance>();inv.equipped=new Dictionary<GearSlot,GearInstance>();inv.gearTemplates=templates;inv.RarityColors=new[]{new Color32(255,255,255,255),new Color32(50,200,50,255),new Color32(100,100,200,255),new Color32(200,180,30,255),new Color32(200,50,50,255)};
