   Check(r,m.title.text==Lang.Get.IdleRewardsTitle&&m.getidle.text==Lang.Get.GetIdle&&m.boostButtonText.text=="<sprite=3>30","Awake binds actual source localized labels andEnergy cost");
   Set(m,"lastOfflineTime",DateTime.Now.AddMinutes(5));Call(m,"CalculateBaseRewards");Check(r,m.CheckTimerInfo()==0&&Get<Rewards>(m,"baseRewards").coin==0&&Get<int>(m,"offlineGearCount")==0,"future wallclock clamps free rewards/gear to0");
   Set(m,"lastOfflineTime",DateTime.Now.AddHours(-24));Call(m,"CalculateBaseRewards");var capped=Get<Rewards>(m,"baseRewards");Check(r,m.CheckTimerInfo()==600&&capped.coin==2400&&capped.talentScroll==300&&capped.weaponToken==120&&Get<int>(m,"offlineGearCount")>=10&&Get<int>(m,"offlineGearCount")<=12,"original free cap600min/10h andoriginal10..12Gear random cap");
   Check(r,capped.gearScrolls.SequenceEqual(new[]{135,180,135,90,135,225}),"source level0 capped six GearScroll totals");
