   Check(r,ES3.Load<string>("OynadigiTumZamanSaniyesi")=="111"&&ES3.Load<string>("timesavedOffline")=="main-loop-marker"&&ES3.Load<float>("saatlikOdulSaniyeToplam")==123f,"offline claim does not replace mainloop3 unrelated timing keys");
   m.ClosePopUp();Check(r,!m.popUpObj.activeSelf,"source popup close hides result presentation");
