   Check(r,Currencys.Coin==244&&Currencys.TalentScroll==30&&Currencys.WeaponToken==12&&inv.inventory.Count==1&&inv.inventory[0].template==preview.template,"real delayed currency/inventory saves survive actual physical reload with original asset identity");
   Check(r,!reopened.collectButton.interactable&&!Click(reopened.collectButton)&&Currencys.Coin==244&&inv.inventory.Count==1,"new manager reload cannot normal-reclaim previous earned interval");
   // Existing finite Energy boost path, without VIP/ad/paid entitlement fabrication.
   Currencys.EnergyFitle(30);Call(reopened,"UpdateBoostUI");Check(r,reopened.boostButton.interactable&&reopened.boostRemaining==3,"earned30Energy enables original finite boost without VIP");int countBefore=inv.inventory.Count;double coinBefore=Currencys.Coin;int talentBefore=Currencys.TalentScroll,weaponBefore=Currencys.WeaponToken;DateTime beforeBoostStamp=ES3.Load<DateTime>("NewlastOfflineTime");
   Check(r,Click(reopened.boostButton)&&Currencys.Energy==0&&reopened.boostRemaining==2&&Currencys.Coin==coinBefore+2400&&Currencys.TalentScroll==talentBefore+300&&Currencys.WeaponToken==weaponBefore+120,"source finite boost spends30Energy then grants exact600min extra scalar rewards");
   Check(r,inv.inventory.Count==countBefore+10&&ES3.Load<int>("boostRemainingB")==2&&ES3.Load<DateTime>("NewlastOfflineTime")==beforeBoostStamp&&!Get<bool>(reopened,"hasUsedExtra"),"boost grants10originalGear, persists decremented count, keeps normal interval baseline, clears transient extra flag");
   Check(r,!reopened.boostButton.interactable&&!Click(reopened.boostButton)&&inv.inventory.Count==countBefore+10,"spentEnergy normal UI cannot repeat boost for free");
   Set(reopened,"lastBoostResetTime",DateTime.Now.AddHours(-25));reopened.boostRemaining=0;Call(reopened,"CheckBoostReset");Check(r,reopened.boostRemaining==2&&ES3.Load<int>("boostRemainingB")==2&&Math.Abs((ES3.Load<DateTime>("lastBoostResetTime")-DateTime.Now).TotalSeconds)<3,"original24hour reset grants2 uses, retaining difference from missing-key default3");
   reopened.boostRemaining=0;Currencys.EnergyFitle(30);Call(reopened,"UpdateBoostUI");Check(r,!reopened.boostButton.interactable&&!Click(reopened.boostButton)&&Currencys.Energy==30,"zero finite uses blocks boost despite sufficientEnergy");
   Flush(currency,inv);Currencys.LoadStartCoin();inv.Load();Check(r,Currencys.Coin==coinBefore+2400&&inv.inventory.Count==countBefore+10&&!GameManager.ViPSinirsizidle,"normal and legitimate finiteEnergy reward persist without creating VIP");
   r.saveFile=OfflineKeyStore.PathFor();Check(r,File.Exists(r.saveFile),"isolated real offline reward disk store exists");r.sourceRules.Add("Separate DateTime.Now NewlastOfflineTime; free cap600min, normal Button eligibility rawminutes>3; actual original templates/inventory save.");r.sourceRules.Add("Default3 boost uses but24h reset2. Cost30Energy, existing VIP flag only, source SpendEnergy return ignored. No ad or entitlement synthesis.");
